package com.ece; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; public class VibrationMonitorTest { @Test public void testNormal() { double avg = VibrationMonitor.calculateAverage(new double[]{1.0,1.5,2.0}); assertEquals(1.5, avg, 0.01); assertEquals("Normal", VibrationMonitor.classifyCondition(avg)); } @Test public void testWarning() { assertEquals("Warning", VibrationMonitor.classifyCondition(5.0)); } @Test public void testSevere() { assertEquals("Severe", VibrationMonitor.classifyCondition(8.5)); } }